const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountIsaPoint = ee.Geometry.Point(139.4925, -20.7297); // Mount Isa coordinates
  const townsvillePoint = ee.Geometry.Point(146.8169, -19.2589); // Townsville coordinates

  const bufferSize = 50000; // 50 km buffer
  const mountIsaRegion = mountIsaPoint.buffer(bufferSize);
  const townsvilleRegion = townsvillePoint.buffer(bufferSize);

  const startDate = '2019-01-27';
  const endDate = '2019-02-10';

  const rainfallThresholdCm = 45;
  const rainfallThresholdMm = rainfallThresholdCm * 10; // Convert cm to mm

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, ee.Date(endDate).advance(1, 'day')) // Filter endDate is exclusive
    .select('precipitation');

  const chirpsSize = await chirps.size().getInfo();

  if (chirpsSize === 0) {
    console.log("No CHIRPS images found for the specified date range.");
    console.log("C1");
    return;
  }

  // Sum precipitation over the period
  const totalRainfall = chirps.sum();

  // Define scale for reduceRegion (CHIRPS resolution is ~5.5 km)
  const scale = 10000; // 10 km scale to ensure efficient computation

  // 3. Processing & Calculation for Mount Isa
  const mountIsaRainfall = await totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(), // Use mean to get average rainfall over the region
    geometry: mountIsaRegion,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const mountIsaValidPixels = await totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mountIsaRegion,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 3. Processing & Calculation for Townsville
  const townsvilleRainfall = await totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: townsvilleRegion,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const townsvilleValidPixels = await totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: townsvilleRegion,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 4. Validation & Final Answer
  if (mountIsaRainfall === null || isNaN(mountIsaRainfall) ||
      townsvilleRainfall === null || isNaN(townsvilleRainfall)) {
    console.log("Calculation resulted in Null or NaN for one or both regions.");
    console.log("C3");
    return;
  }

  if (mountIsaValidPixels === 0) {
    console.log("No valid pixels found for Mount Isa after processing.");
    console.log("C2");
    return;
  }
  if (townsvilleValidPixels === 0) {
    console.log("No valid pixels found for Townsville after processing.");
    console.log("C2");
    return;
  }

  const mountIsaRainfallCm = mountIsaRainfall / 10;
  const townsvilleRainfallCm = townsvilleRainfall / 10;

  console.log(`Mount Isa Avg Rainfall: ${mountIsaRainfallCm.toFixed(2)} cm (Pixels: ${mountIsaValidPixels})`);
  console.log(`Townsville Avg Rainfall: ${townsvilleRainfallCm.toFixed(2)} cm (Pixels: ${townsvilleValidPixels})`);
  console.log(`Threshold: ${rainfallThresholdCm} cm`);

  const mountIsaMetCondition = mountIsaRainfall >= rainfallThresholdMm;
  const townsvilleMetCondition = townsvilleRainfall >= rainfallThresholdMm;

  if (mountIsaMetCondition && townsvilleMetCondition) {
    console.log("A"); // Both regions experienced at least 45 cm
  } else {
    console.log("B"); // At least one region did not meet the condition
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
